CREATE TABLE "auth_user" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "password" varchar(128) NOT NULL,
  "last_login" timestamptz,
  "is_superuser" boolean NOT NULL,
  "username" varchar(150) UNIQUE NOT NULL,
  "first_name" varchar(150) NOT NULL,
  "last_name" varchar(150) NOT NULL,
  "email" varchar(254) NOT NULL,
  "is_staff" boolean NOT NULL,
  "is_active" boolean NOT NULL,
  "date_joined" timestamptz NOT NULL
);

CREATE TABLE "roles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "code" varchar(30) UNIQUE NOT NULL,
  "name" varchar(100) NOT NULL,
  "description" text,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "user_roles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "user_id" integer NOT NULL,
  "role_id" bigint NOT NULL,
  "assigned_at" timestamptz NOT NULL
);

CREATE TABLE "authentication_userprofile" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "user_id" integer UNIQUE NOT NULL,
  "rut" varchar(12) UNIQUE,
  "phone" varchar(20)
);

CREATE TABLE "notification_channels" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "code" varchar(20) UNIQUE NOT NULL,
  "name" varchar(50) NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "clients" (
  "id" uuid PRIMARY KEY NOT NULL,
  "rut" varchar(12) UNIQUE NOT NULL,
  "first_name" varchar(100) NOT NULL,
  "last_name" varchar(100) NOT NULL,
  "phone" varchar(20) NOT NULL,
  "email" varchar(255),
  "password_hash" varchar(255) NOT NULL,
  "notification_channel_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL
);

CREATE TABLE "client_otps" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "client_id" uuid UNIQUE NOT NULL,
  "code_hash" varchar(128) NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "last_sent_at" timestamptz NOT NULL,
  "attempts" smallint NOT NULL,
  "consumed_at" timestamptz,
  "verified_at" timestamptz,
  CHECK ("attempts" >= 0)
);

CREATE TABLE "vehicle_brands" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(50) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "vehicle_models" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "brand_id" bigint NOT NULL,
  "name" varchar(50) NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "vehicles" (
  "id" uuid PRIMARY KEY NOT NULL,
  "client_id" uuid NOT NULL,
  "model_id" bigint NOT NULL,
  "plate" varchar(10) UNIQUE NOT NULL,
  "year" integer NOT NULL,
  "color" varchar(30),
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL
);

CREATE TABLE "services" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(150) UNIQUE NOT NULL,
  "description" text NOT NULL,
  "base_price" numeric(12,2),
  "estimated_duration_minutes" integer,
  "is_active" boolean NOT NULL,
  "is_bookable" boolean NOT NULL,
  CONSTRAINT "service_nonnegative_price" CHECK (("base_price" >= 0 OR "base_price" IS NULL)),
  CONSTRAINT "service_positive_duration" CHECK (("estimated_duration_minutes" >= 1 OR "estimated_duration_minutes" IS NULL)),
  CHECK ("estimated_duration_minutes" >= 0)
);

CREATE TABLE "workshop_appointmentslot" (
  "scheduled_date" timestamptz PRIMARY KEY NOT NULL
);

CREATE TABLE "appointments" (
  "id" uuid PRIMARY KEY NOT NULL,
  "client_id" uuid NOT NULL,
  "vehicle_id" uuid,
  "service_id" bigint,
  "status" varchar(10) NOT NULL,
  "scheduled_date" timestamptz NOT NULL,
  "slot_number" smallint NOT NULL,
  "reported_symptoms" text NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  CONSTRAINT "appointment_slot_one_or_two" CHECK (("slot_number" >= 1 AND "slot_number" <= 2)),
  CHECK ("slot_number" >= 0)
);

CREATE TABLE "workshop_bookingverification" (
  "id" uuid PRIMARY KEY NOT NULL,
  "rut" varchar(12) NOT NULL,
  "payload_hash" varchar(64) NOT NULL,
  "code_hash" varchar(128) NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "attempts" smallint NOT NULL,
  "consumed_at" timestamptz,
  CHECK ("attempts" >= 0)
);

CREATE TABLE "workshop_clientprofilechange" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "client_id" uuid UNIQUE NOT NULL,
  "payload" jsonb NOT NULL,
  "email_at_request" varchar(254) NOT NULL,
  "code_hash" varchar(128) NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "last_sent_at" timestamptz NOT NULL,
  "attempts" smallint NOT NULL,
  "consumed_at" timestamptz,
  CHECK ("attempts" >= 0)
);

CREATE TABLE "item_categories" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL,
  "is_active" boolean NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "item_brands" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) NOT NULL,
  "is_active" boolean NOT NULL,
  CONSTRAINT "item_brand_name_required" CHECK (NOT TRIM("name") = '')
);

CREATE TABLE "inventory_items" (
  "id" uuid PRIMARY KEY NOT NULL,
  "category_id" bigint NOT NULL,
  "brand_id" bigint NOT NULL,
  "sku" varchar(50) UNIQUE NOT NULL,
  "name" varchar(150) NOT NULL,
  "description" text,
  "unit_price" numeric(12,2) NOT NULL,
  "current_stock" integer NOT NULL,
  "minimum_stock" integer NOT NULL,
  "is_published" boolean NOT NULL,
  "public_title" varchar(150),
  "public_description" text,
  "public_price" numeric(10,0),
  "public_image" varchar(500),
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL
);

CREATE TABLE "work_order_statuses" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "code" varchar(30) UNIQUE NOT NULL,
  "name" varchar(50) NOT NULL,
  "sequence_order" integer NOT NULL,
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "work_orders" (
  "appointment_id" uuid UNIQUE,
  "id" uuid PRIMARY KEY NOT NULL,
  "folio_number" integer UNIQUE NOT NULL,
  "tracking_code" varchar(14) UNIQUE NOT NULL,
  "tracking_token" varchar(32) UNIQUE NOT NULL,
  "vehicle_id" uuid NOT NULL,
  "assigned_mechanic_id" integer,
  "status_id" bigint NOT NULL,
  "client_observations" text,
  "technical_diagnosis" text,
  "ai_diagnostic_suggestion" text,
  "estimated_delivery_date" timestamptz,
  "closed_at" timestamptz,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL
);

CREATE TABLE "work_order_checkins" (
  "id" uuid PRIMARY KEY NOT NULL,
  "work_order_id" uuid UNIQUE NOT NULL,
  "receptionist_id" integer,
  "initial_odometer" integer,
  "fuel_level" varchar(20) NOT NULL,
  "has_spare_tire" boolean,
  "has_jack_and_tools" boolean,
  "bodywork_details" text,
  "additional_equipment" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL,
  CHECK ("initial_odometer" >= 0)
);

CREATE TABLE "work_order_photos" (
  "id" uuid PRIMARY KEY NOT NULL,
  "checkin_id" uuid NOT NULL,
  "photo_cloudinary_url" text NOT NULL,
  "public_id" varchar(100),
  "created_at" timestamptz NOT NULL
);

CREATE TABLE "work_order_items" (
  "id" uuid PRIMARY KEY NOT NULL,
  "work_order_id" uuid NOT NULL,
  "item_id" uuid NOT NULL,
  "added_by_user_id" integer,
  "quantity" integer NOT NULL,
  "request_id" uuid,
  "unit_price" numeric(12,2) NOT NULL,
  "created_at" timestamptz NOT NULL,
  CHECK ("quantity" >= 0)
);

CREATE TABLE "work_order_status_history" (
  "id" uuid PRIMARY KEY NOT NULL,
  "work_order_id" uuid NOT NULL,
  "from_status_id" bigint,
  "to_status_id" bigint NOT NULL,
  "changed_by_id" integer,
  "notes" text,
  "changed_at" timestamptz NOT NULL
);

CREATE TABLE "quotes" (
  "id" uuid PRIMARY KEY NOT NULL,
  "work_order_id" uuid,
  "client_id" uuid NOT NULL,
  "subtotal_amount" numeric(12,2) NOT NULL,
  "service_name" varchar(250) NOT NULL,
  "service_amount" numeric(12,2),
  "tax_rate" numeric(5,2) NOT NULL,
  "tax_amount" numeric(12,2) NOT NULL,
  "total_amount" numeric(12,2) NOT NULL,
  "is_approved" boolean NOT NULL,
  "pdf_cloudinary_url" text,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  CONSTRAINT "quote_nonnegative_amounts" CHECK (("subtotal_amount" >= 0 AND "tax_amount" >= 0 AND "total_amount" >= 0)),
  CONSTRAINT "quote_valid_tax_rate" CHECK (("tax_rate" >= 0 AND "tax_rate" <= 100)),
  CONSTRAINT "quote_total_consistent" CHECK ("total_amount" = ("subtotal_amount" + "tax_amount")),
  CONSTRAINT "quote_service_snapshot_consistent" CHECK ((("service_amount" IS NULL AND "service_name" = '') OR (NOT ("service_name" = '') AND "service_amount" >= 0 AND "service_amount" IS NOT NULL)))
);

CREATE TABLE "quote_items" (
  "id" uuid PRIMARY KEY NOT NULL,
  "quote_id" uuid NOT NULL,
  "item_id" uuid NOT NULL,
  "brand_name" varchar(100) NOT NULL,
  "quantity" integer NOT NULL,
  "unit_price" numeric(12,2) NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "quote_item_positive_values" CHECK (("quantity" >= 1 AND "unit_price" >= 0)),
  CHECK ("quantity" >= 0)
);

CREATE TABLE "workshop_emaildelivery" (
  "id" uuid PRIMARY KEY NOT NULL,
  "payload" jsonb NOT NULL,
  "kind" varchar(20) NOT NULL,
  "target_id" uuid NOT NULL,
  "status" varchar(12) NOT NULL,
  "attempts" smallint NOT NULL,
  "available_at" timestamptz NOT NULL,
  "locked_at" timestamptz,
  "last_error" varchar(255) NOT NULL,
  "created_at" timestamptz NOT NULL,
  "sent_at" timestamptz,
  CHECK ("attempts" >= 0)
);

CREATE TABLE "demand_forecast_snapshots" (
  "id" uuid PRIMARY KEY NOT NULL,
  "period" varchar(10) NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "forecast" jsonb NOT NULL,
  "generated_at" timestamptz NOT NULL
);

