COMMENT ON TABLE "auth_user" IS 'Usuarios del personal en Django. Los clientes del portal se registran en clients.';

COMMENT ON COLUMN "clients"."phone" IS 'Contacto único cuando se informa. Se ignoran separadores y variantes del prefijo móvil chileno.';

COMMENT ON COLUMN "clients"."email" IS 'Contacto único cuando se informa, sin distinguir mayúsculas ni espacios exteriores.';

COMMENT ON TABLE "workshop_appointmentslot" IS 'Registro de bloqueo para asignar los cupos de un horario. No existe una clave foránea entre esta tabla y appointments.';

COMMENT ON TABLE "appointments" IS 'Estado definido mediante TextChoices. La restricción unique_active_appointment_capacity es parcial y aplica a citas distintas de CANCELADA o RECHAZADA.';

COMMENT ON COLUMN "appointments"."slot_number" IS 'Número de cupo asignado por Django. El taller admite dos cupos por horario.';

COMMENT ON COLUMN "inventory_items"."brand_id" IS 'Obligatorio. La migración usa Marca por identificar para insumos anteriores sin marca registrada.';

COMMENT ON COLUMN "inventory_items"."public_image" IS 'URL HTTPS de Cloudinary o ruta conservada de una imagen local anterior.';

COMMENT ON COLUMN "work_orders"."appointment_id" IS 'Una cita puede originar una sola OT. Una OT puede registrarse sin cita.';

COMMENT ON COLUMN "work_orders"."tracking_code" IS 'Código público de seguimiento.';

COMMENT ON COLUMN "work_order_checkins"."additional_equipment" IS 'Equipamiento y estado observados al ingresar el vehículo.';

COMMENT ON COLUMN "work_order_items"."unit_price" IS 'Importe unitario registrado al asociar el insumo.';

COMMENT ON TABLE "work_order_status_history" IS 'Registra el estado anterior y el nuevo. El estado vigente se consulta en work_orders.';

COMMENT ON COLUMN "quotes"."service_name" IS 'Nombre y descripción del servicio al emitir la cotización.';

COMMENT ON COLUMN "quotes"."service_amount" IS 'Monto neto del servicio al emitir la cotización.';

COMMENT ON COLUMN "quote_items"."brand_name" IS 'Marca registrada al emitir la cotización.';

COMMENT ON COLUMN "quote_items"."unit_price" IS 'Importe unitario registrado al emitir la cotización.';

COMMENT ON TABLE "workshop_emaildelivery" IS 'Cola de notificaciones. kind indica el tipo de entidad referida por target_id. La unicidad unique_client_welcome_notification solo aplica a kind = welcome.';

COMMENT ON TABLE "demand_forecast_snapshots" IS 'Resultado de proyección almacenado por tipo de período y rango.';

ALTER TABLE "user_roles" ADD FOREIGN KEY ("user_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_roles" ADD FOREIGN KEY ("role_id") REFERENCES "roles" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "authentication_userprofile" ADD FOREIGN KEY ("user_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

