ALTER TABLE "client_otps" ADD FOREIGN KEY ("client_id") REFERENCES "clients" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "vehicle_models" ADD FOREIGN KEY ("brand_id") REFERENCES "vehicle_brands" ("id") DEFERRABLE INITIALLY IMMEDIATE;

