ALTER TABLE "vehicles" ADD FOREIGN KEY ("model_id") REFERENCES "vehicle_models" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "appointments" ADD FOREIGN KEY ("client_id") REFERENCES "clients" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "appointments" ADD FOREIGN KEY ("vehicle_id") REFERENCES "vehicles" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "appointments" ADD FOREIGN KEY ("service_id") REFERENCES "services" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "workshop_clientprofilechange" ADD FOREIGN KEY ("client_id") REFERENCES "clients" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("category_id") REFERENCES "item_categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_items" ADD FOREIGN KEY ("brand_id") REFERENCES "item_brands" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_orders" ADD FOREIGN KEY ("appointment_id") REFERENCES "appointments" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_orders" ADD FOREIGN KEY ("vehicle_id") REFERENCES "vehicles" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_orders" ADD FOREIGN KEY ("assigned_mechanic_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_orders" ADD FOREIGN KEY ("status_id") REFERENCES "work_order_statuses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_checkins" ADD FOREIGN KEY ("work_order_id") REFERENCES "work_orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_checkins" ADD FOREIGN KEY ("receptionist_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_photos" ADD FOREIGN KEY ("checkin_id") REFERENCES "work_order_checkins" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_items" ADD FOREIGN KEY ("work_order_id") REFERENCES "work_orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_items" ADD FOREIGN KEY ("item_id") REFERENCES "inventory_items" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_items" ADD FOREIGN KEY ("added_by_user_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_status_history" ADD FOREIGN KEY ("work_order_id") REFERENCES "work_orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_status_history" ADD FOREIGN KEY ("from_status_id") REFERENCES "work_order_statuses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "work_order_status_history" ADD FOREIGN KEY ("to_status_id") REFERENCES "work_order_statuses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

